(ns exercises.lesson07.native-shell-test
  (:require [cheshire.core :as json]
            [clojure.string :as string]
            [clojure.test :refer [deftest is testing]]
            [exercises.lesson07.brew :as brew]
            [exercises.lesson07.native-shell :as n]
            [exercises.lesson07.sse]))

(deftest shell-request-test
  (is (true? (n/shell-request? {:headers {"user-agent" n/shell-ua}})))
  (is (false? (n/shell-request? {:headers {"user-agent" "Mozilla/5.0 (Macintosh) Safari/605.1.15"}})))
  (is (false? (n/shell-request? {:headers {}}))))

(defn- script-of [event]
  (second (re-find #"(?s)<script[^>]*>(.*)</script>" event)))

(deftest bridge-script-test
  (let [ev (n/bridge-script {:type "haptic" :style "success"})]
    (testing "it is an execute-script event: a self-removing script appended to body"
      (is (string/starts-with? ev "event: datastar-patch-elements\ndata: selector body\ndata: mode append\n"))
      (is (string/includes? ev "data-effect=\"el.remove()\"")))
    (testing "the script posts the message as a JSON object"
      (is (= "window.BrewShell.post({\"type\":\"haptic\",\"style\":\"success\"})" (script-of ev)))))
  (testing "a message can't close or confuse the script tag"
    (doseq [body ["</script><script>alert(1)" "<!--<script>"]]
      (let [ev (n/bridge-script {:body body})]
        (is (not (string/includes? (script-of ev) "<")) "the script text has no <")
        (is (= {:body body}
               (-> (script-of ev) (string/replace #"^window\.BrewShell\.post\(|\)$" "")
                   (json/parse-string true))))))))

(def two-orders
  (-> brew/initial-state
      (assoc-in [:carts "ada"] [{:drink :latte :size :medium :milk :oat :qty 1}])
      (brew/handle-command {:type :place-order :sid "ada" :customer "Ada"})
      (assoc-in [:carts "grace"] [{:drink :mocha :size :small :milk :whole :qty 1}])
      (brew/handle-command {:type :place-order :sid "grace" :customer "Grace"})))

(defn- advance [state & ids] (reduce #(brew/handle-command %1 {:type :advance :id %2}) state ids))

(deftest ready-notifications-test
  (testing "nothing became ready"
    (is (empty? (n/ready-notifications two-orders (advance two-orders 1)))))
  (testing "an order that just became ready"
    (let [making (advance two-orders 1 2)]
      (is (= [{:sid "ada" :message "Ada, your order #1 is ready."}]
             (n/ready-notifications making (advance making 1))))
      (testing "two at once, in order-id order"
        (is (= ["ada" "grace"] (map :sid (n/ready-notifications making (advance making 2 1))))))))
  (testing "an order that was already ready is not notified again"
    (let [ready (advance two-orders 1 1)]
      (is (empty? (n/ready-notifications ready (brew/handle-command ready {:type :toggle-stock :milk :oat}))))))
  (testing "a picked-up order is not a notification"
    (let [ready (advance two-orders 1 1)]
      (is (empty? (n/ready-notifications ready (advance ready 1)))))))

(defn- call [handler method uri & {:keys [signals sid ua]}]
  (handler (cond-> {:request-method method :uri uri :headers {"datastar-request" "true"}}
             ua (assoc-in [:headers "user-agent"] ua)
             sid (assoc-in [:headers "cookie"] (str "sid=" sid))
             signals (assoc :body (java.io.ByteArrayInputStream. (.getBytes (json/generate-string signals) "UTF-8"))))))

(deftest close-during-broadcast-test
  (testing "a stream that closes mid-broadcast stays unsubscribed, and later broadcasts still work"
    (let [hub (n/make-hub)
          !state (atom brew/initial-state)
          sent (atom [])]
      (n/subscribe! hub :ada (fn [_] (n/unsubscribe! hub :ada)) {:kind :customer :sid "ada"})
      (n/subscribe! hub :sam #(swap! sent conj %) {:kind :board})
      (n/broadcast! hub !state)
      (is (= #{:sam} (set (keys @hub))))
      (swap! !state brew/handle-command {:type :toggle-stock :milk :oat})
      (is (= [:sam] (n/broadcast! hub !state)))
      (is (= 2 (count @sent))))))

(deftest native-routes-test
  (let [!state (atom brew/initial-state)
        hub (n/make-hub)
        app (n/app !state hub)
        sent (atom [])
        pushed (atom [])]
    (with-redefs [n/push! (fn [token message] (swap! pushed conj [token message]))]
      (n/watch! !state hub)
      (testing "the same route renders for the web and for the shell"
        (let [web (:body (call app :get "/"))
              shell (:body (call app :get "/" :ua n/shell-ua))]
          (is (string/includes? web "<nav"))
          (is (not (string/includes? shell "<nav")))
          (is (not (string/includes? shell "<h1>")))
          (is (string/includes? shell "window.BrewShell = {"))
          (is (string/includes? shell "data-on:brew:native__window="))))
      (testing "path-config is JSON the shell reads at launch"
        (let [resp (call app :get "/native/path-config")]
          (is (= "application/json" (get-in resp [:headers "Content-Type"])))
          (is (= "push" (-> resp :body (json/parse-string true) :rules second :presentation)))))
      (testing "the device route stores the push token for this sid"
        (is (= 204 (:status (call app :post "/native/device" :sid "ada" :signals {:pushToken "tok-1"}))))
        (is (= "tok-1" (get-in @!state [:devices "ada"]))))
      (testing "a ready order goes to the open stream as a bridge call"
        (n/subscribe! hub :ada-stream #(swap! sent conj %) {:kind :customer :sid "ada" :shell? true})
        (call app :post "/cart/items" :sid "ada" :signals {:drink "latte" :size "medium" :milk "oat" :qty 1})
        (call app :post "/orders" :sid "ada" :signals {:customer "Ada"})
        (call app :post "/orders/1/advance")
        (call app :post "/orders/1/advance")
        (is (some #(string/includes? % "BrewShell.post({\"type\":\"notify\"") @sent))
        (is (empty? @pushed)))
      (testing "with no open stream it falls back to a push to the device token"
        (n/unsubscribe! hub :ada-stream)
        (call app :post "/cart/items" :sid "ada" :signals {:drink "mocha" :size "small" :milk "whole" :qty 1})
        (call app :post "/orders" :sid "ada" :signals {:customer "Ada"})
        (call app :post "/orders/2/advance")
        (call app :post "/orders/2/advance")
        (is (= [["tok-1" "Ada, your order #2 is ready."]] @pushed)))
      (testing "choosing a drink is a POST /draft command, stored for the tab"
        (let [{:keys [status body]} (call app :post "/draft" :sid "ada" :signals {:tabid "t1" :drink "chai" :size "small" :milk "oat"})]
          (is (= 200 status))
          (is (string/includes? body "{\"size\":\"medium\"}"))
          (is (= {:drink :chai :size :medium :milk :oat} (get-in @!state [:tabs "t1" :draft])))
          (is (string/includes? (n/html (n/view-for @!state {:kind :customer :sid "ada" :tabid "t1" :shell? true}))
                                "<option selected=\"\" value=\"medium\">"))
          (testing "another tab of the same browser keeps its own draft"
            (is (string/includes? (n/html (n/view-for @!state {:kind :customer :sid "ada" :tabid "t2"}))
                                  "<option selected=\"\" value=\"latte\">")))))
      (testing "a failed command's error is server state, drawn in that tab's view"
        (is (= 204 (:status (call app :post "/orders" :sid "ada" :signals {:tabid "t1" :customer "Ada"}))))
        (is (string/includes? (n/html (n/view-for @!state {:kind :customer :sid "ada" :tabid "t1"}))
                              "<p class=\"error\">Your cart is empty.</p>"))
        (is (not (string/includes? (n/html (n/view-for @!state {:kind :customer :sid "ada" :tabid "t1"}))
                                   "data-ignore-morph"))))
      (testing "the page seeds a tab id on <body>"
        (is (string/includes? (:body (call app :get "/" :ua n/shell-ua))
                              "data-signals:tabid__ifmissing=\"crypto.randomUUID()\"")))
      (testing "malformed signals are {}, not a 500"
        (is (= {} (exercises.lesson07.sse/read-signals {:request-method :post
                                              :body (java.io.ByteArrayInputStream. (.getBytes "not json" "UTF-8"))}))))
      (testing "an order screen is only for its own sid"
        (is (= 200 (:status (call app :get "/orders/1" :sid "ada"))))
        (is (= 404 (:status (call app :get "/orders/1" :sid "grace"))))))))
